window.REPORT_PRELOAD_CACHE["TME.html"] = {"version":"e3431b58b5084e16e63bb993e81cc2f06eb877afea2f98a8b14d7d2439ef617d","html":"<!DOCTYPE html>\n<html lang=\"zh-CN\" class=\"scroll-smooth\">\n<head>\n <meta charset=\"UTF-8\" />\n <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n <title>腾讯音乐娱乐集团 Tencent Music (NYSE: TME) 深度研究报告：中国在线音乐付费长牛、SVIP与喜马拉雅整合双轮驱动与高现金回报堡垒</title>\n <!-- Tailwind CSS -->\n <script src=\"https://cdn.tailwindcss.com\"></script>\n <!-- Chart.js -->\n <script src=\"https://cdn.jsdelivr.net/npm/chart.js\"></script>\n <!-- Google Fonts: Inter + Noto Sans SC + JetBrains Mono -->\n <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;600;700&family=Noto+Sans+SC:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n\n <script>\n tailwind.config = {\n darkMode: 'class',\n theme: {\n extend: {\n fontFamily: {\n sans: ['Inter', 'Noto Sans SC', 'system-ui', '-apple-system', 'sans-serif'],\n mono: ['JetBrains Mono', 'monospace'],\n },\n colors: {\n navy: {\n 950: '#070B14',\n 900: '#0F172A',\n 800: '#1E293B',\n 700: '#334155',\n },\n tmeblue: {\n 350: '#38BDF8',\n 400: '#0284C7',\n 500: '#0284C7',\n 600: '#0369A1',\n 700: '#075985',\n },\n tmeviolet: {\n 400: '#A855F7',\n 500: '#8B5CF6',\n 600: '#7C3AED',\n }\n }\n }\n }\n }\n </script>\n\n <style>\n ::-webkit-scrollbar {\n width: 6px;\n height: 6px;\n }\n ::-webkit-scrollbar-track {\n background: transparent;\n }\n ::-webkit-scrollbar-thumb {\n background: #94A3B8;\n border-radius: 3px;\n }\n .dark ::-webkit-scrollbar-thumb {\n background: #475569;\n }\n\n @media print {\n #sidebar, #mobile-header, #theme-toggle-btn, .no-print {\n display: none !important;\n }\n main {\n margin-left: 0 !important;\n padding: 0 !important;\n }\n section {\n break-inside: avoid;\n }\n }\n\n .report-card {\n transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;\n }\n .report-card:hover {\n transform: translateY(-2px);\n }\n\n .nav-link.active {\n background: linear-gradient(90deg, rgba(2, 132, 199, 0.24) 0%, rgba(139, 92, 246, 0.06) 100%);\n border-left: 3px solid #0284C7;\n color: #FFFFFF;\n font-weight: 600;\n }\n </style>\n</head>\n<body class=\"bg-[#F8FAFC] text-[#1E293B] dark:bg-navy-950 dark:text-slate-100 antialiased selection:bg-tmeblue-500 selection:text-white transition-colors duration-200\">\n\n <!-- 顶部阅读进度条 -->\n <div class=\"fixed top-0 left-0 right-0 h-1 z-50 bg-slate-200/70 dark:bg-navy-800\">\n <div id=\"reading-progress\" class=\"h-full bg-gradient-to-r from-tmeblue-500 via-sky-400 to-tmeviolet-500 w-0 transition-all duration-150\"></div>\n </div>\n\n <!-- 移动端顶部导航栏 -->\n <header id=\"mobile-header\" class=\"lg:hidden sticky top-0 z-40 bg-navy-900 text-white border-b border-slate-800 px-4 py-3 flex items-center justify-between shadow-md\">\n <div class=\"flex items-center space-x-2.5\">\n <div class=\"w-8 h-8 rounded-lg bg-gradient-to-br from-tmeblue-400 to-tmeviolet-600 flex items-center justify-center font-extrabold text-white text-xs shadow\">\n TME\n </div>\n <div>\n <div class=\"text-[11px] text-sky-400 font-semibold tracking-wider uppercase\">NYSE: TME · Audio Streaming</div>\n <div class=\"text-sm font-bold leading-tight\">腾讯音乐 深度研究报告</div>\n </div>\n </div>\n <div class=\"flex items-center space-x-2\">\n <button onclick=\"toggleTheme()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-slate-300\" aria-label=\"切换阅读主题\">\n <svg class=\"w-5 h-5 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n <svg class=\"w-5 h-5 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n </button>\n <button id=\"mobile-menu-btn\" onclick=\"toggleMobileMenu()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-white\" aria-label=\"打开目录\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M4 6h16M4 12h16M4 18h16\"/></svg>\n </button>\n </div>\n </header>\n\n <!-- 移动端抽屉菜单 -->\n <div id=\"mobile-drawer\" class=\"fixed inset-0 z-50 hidden lg:hidden\">\n <div class=\"fixed inset-0 bg-slate-900/70 backdrop-blur-sm\" onclick=\"toggleMobileMenu()\"></div>\n <nav class=\"relative w-72 max-w-[80vw] h-full bg-navy-900 text-slate-300 flex flex-col justify-between p-5 overflow-y-auto shadow-2xl\">\n <div>\n <div class=\"flex items-center justify-between pb-4 border-b border-slate-800\">\n <span class=\"font-bold text-white text-base\">TME 研报目录导航</span>\n <button onclick=\"toggleMobileMenu()\" class=\"p-1.5 rounded-lg text-slate-400 hover:text-white\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M6 18L18 6M6 6l12 12\"/></svg>\n </button>\n </div>\n <ul class=\"mt-4 space-y-1.5 text-sm\">\n <li><a href=\"#sec-exec\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">00. 执行摘要与核心指标</a></li>\n <li><a href=\"#sec-biz\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">01. 业务架构与订阅/IP演进</a></li>\n <li><a href=\"#sec-moat\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">02. 版权壁垒与生态护城河</a></li>\n <li><a href=\"#sec-comp\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">03. 全球流媒体与文娱横向对比</a></li>\n <li><a href=\"#sec-fin\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">04. 财务健康与回购复利模型</a></li>\n <li><a href=\"#sec-inv\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">05. 投资决策与三情景估值</a></li>\n <li><a href=\"#sec-kpi\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">06. 季度跟踪 KPI 核查清单</a></li>\n </ul>\n </div>\n <div class=\"pt-4 border-t border-slate-800 text-xs text-slate-400\">\n <p>全球科技与数字文娱研究组</p>\n <p class=\"mt-1\">数据基准：2026年11月 (Q3 26 / FY26E)</p>\n </div>\n </nav>\n </div>\n\n <!-- 桌面端左侧固定侧边导航栏 -->\n <aside id=\"sidebar\" class=\"hidden lg:flex fixed top-0 left-0 bottom-0 w-[280px] bg-[#0F172A] text-slate-300 flex-col justify-between border-r border-slate-800 z-30 select-none\">\n <div>\n <div class=\"p-5 border-b border-slate-800/80\">\n <div class=\"flex items-center space-x-3\">\n <div class=\"w-10 h-10 rounded-xl bg-gradient-to-br from-tmeblue-400 via-sky-500 to-tmeviolet-600 flex items-center justify-center text-white font-extrabold text-base shadow-lg shadow-sky-500/25\">\n TME\n </div>\n <div>\n <span class=\"inline-block text-[10px] font-bold tracking-widest uppercase text-sky-400 bg-sky-500/15 px-2 py-0.5 rounded\">NYSE: TME</span>\n <h2 class=\"text-white font-bold text-base mt-0.5 tracking-tight\">腾讯音乐深度研报</h2>\n </div>\n </div>\n <p class=\"text-xs text-slate-400 mt-2.5 leading-relaxed\">\n 中国在线音乐付费长牛 · SVIP高单价驱动与喜马拉雅深度并表协同\n </p>\n </div>\n\n <div class=\"px-5 py-3 bg-navy-950/70 border-b border-slate-800/80 space-y-1.5 text-xs\">\n <div class=\"flex items-center justify-between\">\n <span class=\"text-slate-400\">参考股价 (52周区间)</span>\n <span class=\"font-mono font-bold text-white\">~$9.15 <span class=\"text-slate-400 text-[10px]\">($7.66-$19.45)</span></span>\n </div>\n <div class=\"flex items-center justify-between\">\n <span class=\"text-slate-400\">2026E 调整后净利润</span>\n <span class=\"font-mono font-bold text-emerald-400\">~RMB 9.8B <span class=\"text-slate-400\">(+5.2%)</span></span>\n </div>\n <div class=\"flex items-center justify-between pt-1 border-t border-slate-800/70\">\n <span class=\"text-slate-400\">远期估值与市值</span>\n <span class=\"font-mono font-bold text-sky-400\">~10.4x P/E · 市值 ~$11.1B</span>\n </div>\n </div>\n\n <div class=\"px-3 py-3.5 overflow-y-auto max-h-[calc(100vh-310px)]\">\n <div class=\"px-3 mb-2 text-[11px] font-semibold uppercase tracking-wider text-slate-500\">核心研究章节</div>\n <nav id=\"desktop-nav\" class=\"space-y-1 text-[13px]\">\n <a href=\"#sec-exec\" data-target=\"sec-exec\" class=\"nav-link active flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-sky-400 mr-2\">00</span>执行摘要与核心指标</span>\n </a>\n <a href=\"#sec-biz\" data-target=\"sec-biz\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">01</span>业务架构与订阅/IP演进</span>\n </a>\n <a href=\"#sec-moat\" data-target=\"sec-moat\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">02</span>版权壁垒与生态护城河</span>\n </a>\n <a href=\"#sec-comp\" data-target=\"sec-comp\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">03</span>全球流媒体与文娱横向对比</span>\n </a>\n <a href=\"#sec-fin\" data-target=\"sec-fin\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">04</span>财务健康与回购复利模型</span>\n </a>\n <a href=\"#sec-inv\" data-target=\"sec-inv\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">05</span>投资决策与三情景估值</span>\n </a>\n <a href=\"#sec-kpi\" data-target=\"sec-kpi\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">06</span>季度跟踪 KPI 核查清单</span>\n </a>\n </nav>\n </div>\n </div>\n\n <div class=\"p-4 border-t border-slate-800/80 bg-navy-950/50 space-y-2.5\">\n <div class=\"flex items-center justify-between\">\n <span class=\"text-xs text-slate-400\">阅读模式切换</span>\n <button id=\"theme-toggle-btn\" onclick=\"toggleTheme()\" class=\"flex items-center space-x-1.5 px-2.5 py-1.5 rounded-lg bg-navy-800 hover:bg-navy-700 text-xs font-medium text-slate-200 border border-slate-700 transition cursor-pointer\">\n <svg class=\"w-3.5 h-3.5 text-sky-400 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n <svg class=\"w-3.5 h-3.5 text-sky-500 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n <span class=\"dark:hidden\">深色护眼模式</span>\n <span class=\"hidden dark:inline\">机构亮色模式</span>\n </button>\n </div>\n <button onclick=\"window.print()\" class=\"w-full flex items-center justify-center space-x-2 py-2 px-3 rounded-lg bg-gradient-to-r from-tmeblue-500 to-tmeviolet-600 hover:from-tmeblue-600 hover:to-tmeviolet-700 text-white text-xs font-extrabold transition shadow-sm cursor-pointer\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z\"/></svg>\n <span>打印 / 导出 PDF 研报</span>\n </button>\n </div>\n </aside>\n\n <!-- 主内容区 -->\n <main class=\"lg:ml-[280px] min-h-screen\">\n <div class=\"max-w-6xl mx-auto px-4 sm:px-8 py-8 lg:py-12 space-y-12\">\n\n <!-- 00. 封面与执行摘要 -->\n <section id=\"sec-exec\" class=\"scroll-mt-20\">\n <div class=\"flex flex-wrap items-center justify-between gap-3 mb-4 text-xs text-slate-500 dark:text-slate-400\">\n <div class=\"flex flex-wrap items-center gap-2\">\n <span class=\"px-2.5 py-1 rounded-md bg-tmeblue-500/15 text-tmeblue-600 dark:text-tmeblue-400 font-bold border border-tmeblue-500/30\">评级：买入 / 高增长数字文娱底仓</span>\n <span class=\"px-2.5 py-1 rounded-md bg-slate-200/70 dark:bg-navy-800 text-slate-700 dark:text-slate-300 font-medium\">周期：2026Q3 财报验证与 SVIP / 喜马拉雅并表爆发期</span>\n </div>\n <div class=\"flex items-center space-x-3 font-mono\">\n <span>覆盖时间：2026年11月</span>\n <span>NYSE: TME</span>\n </div>\n </div>\n\n <div class=\"relative overflow-hidden rounded-2xl bg-gradient-to-br from-navy-900 via-navy-800 to-slate-900 text-white p-6 sm:p-10 shadow-xl border border-slate-700/70\">\n <div class=\"absolute inset-0 opacity-10 pointer-events-none\" style=\"background-image: radial-gradient(#0284C7 1.2px, transparent 1.2px); background-size: 24px 24px;\"></div>\n <div class=\"relative z-10\">\n <div class=\"inline-flex items-center space-x-2 px-3 py-1 rounded-full bg-tmeblue-500/20 border border-tmeblue-400/40 text-sky-300 text-xs font-semibold mb-4\">\n <span class=\"w-2 h-2 rounded-full bg-sky-400 animate-pulse\"></span>\n <span>CORE THESIS · 在线音乐付费率突破长牛 × SVIP 超高 ARPU 引擎 × 喜马拉雅并表生态协同 × 现金与股份回购双轮回报</span>\n </div>\n <h1 class=\"text-2xl sm:text-4xl font-extrabold tracking-tight leading-tight text-white\">\n 腾讯音乐娱乐集团 Tencent Music (NYSE: TME) 深度研究报告：中国在线音乐付费长牛、SVIP与喜马拉雅整合双轮驱动与高现金回报堡垒\n </h1>\n <p class=\"mt-4 text-sm sm:text-base text-slate-300 max-w-4xl leading-relaxed\">\n 腾讯音乐发布 <strong class=\"text-white\">2026年第三季度财报</strong>：单季总收入达 <strong class=\"text-sky-300\">RMB 89.4亿元</strong>（同比增长 <strong class=\"text-emerald-400\">+5.6%</strong>），非国际财务报告准则（Non-IFRS）净利润达 <strong class=\"text-emerald-400\">RMB 24.5亿元</strong>（同比增长 <strong class=\"text-white\">+2.1%</strong>）。\n 尽管社交娱乐服务因行业竞争调整延续同比收缩（-15.7%），但核心的<strong class=\"text-sky-300\">音乐订阅（Membership）收入逆势增长 9.2% 至 RMB 49.9亿元</strong>，同时营销与消费类服务（线下演唱会与艺人周边）强劲飙升 <strong class=\"text-emerald-400\">+12.1%</strong>。\n 叠加顺利并表的音频平台喜马拉雅与高额股东回购（Q3 单季在公开市场回购 3,470 万股 ADS，耗资约 <strong class=\"text-white\">$3.0亿</strong>，上半年已回购 $4.0亿），TME 持续巩固其全球现金流最健康、商业化效率最高的数字音乐巨头地位。\n </p>\n\n <div class=\"mt-6 pt-6 border-t border-slate-700/80 grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">音乐订阅持续高质量增长</div>\n <div class=\"text-white font-semibold\">Q3 音乐订阅收入 RMB 49.9亿（+9.2% YoY），SVIP（超级会员）付费用户数与 ARPPU 维持双位数强劲扩张</div>\n </div>\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">IP 衍生与演出生态爆发</div>\n <div class=\"text-sky-300 font-semibold\">营销与消费类服务收入增至 RMB 27.0亿（+12.1% YoY），线下演唱会与艺人周边成第二增长曲线</div>\n </div>\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">巨额现金与密集回购</div>\n <div class=\"text-emerald-400 font-semibold\">现金及短期投资增至 RMB 515亿元，前三季度累计回购超 $7.0亿美元，构建极强安全垫</div>\n </div>\n </div>\n </div>\n </div>\n\n <div class=\"grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4 mt-6\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>最新股价与总市值</span>\n <span class=\"p-1.5 rounded-lg bg-tmeblue-500/15 text-tmeblue-600 dark:text-tmeblue-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M13 7h8m0 0v8m0-8l-8 8-4-4-6 6\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$111.3B</span>\n <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/15 px-2 py-0.5 rounded\">~$9.15</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 美股 ADR 当前报价 $9.15，对应总市值约 111 亿美元，估值处于极具安全边际的 10.4x P/E 区间。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>2026Q3 经调整 Non-IFRS 净利</span>\n <span class=\"p-1.5 rounded-lg bg-emerald-500/15 text-emerald-600 dark:text-emerald-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-2xl sm:text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">RMB 2.45B</span>\n <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/15 px-2 py-0.5 rounded\">+2.1% YoY</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 经调整净利润达 24.5 亿元人民币，展现出音乐订阅高毛利持续对冲社交娱乐业务下行的稳健盈利能力。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>现金、存款及短期投资总额</span>\n <span class=\"p-1.5 rounded-lg bg-tmeviolet-500/15 text-tmeviolet-600 dark:text-tmeviolet-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">RMB 51.5B</span>\n <span class=\"text-xs font-bold text-tmeviolet-600 dark:text-tmeviolet-400 bg-tmeviolet-500/15 px-2 py-0.5 rounded\">~$7.5B 美元</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 截至 2026 年 9 月底，现金储备增至 514.9 亿元（含 9 月成功发行的 10 亿美元高级无担保优先票据），财务实力堪称堡垒。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>年度股东现金回报 (回购+股息)</span>\n <span class=\"p-1.5 rounded-lg bg-sky-500/15 text-sky-600 dark:text-sky-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">&gt;$700M</span>\n <span class=\"text-xs font-bold text-sky-600 dark:text-sky-400 bg-sky-500/15 px-2 py-0.5 rounded\">股息率 ~2.7%</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 2026 年前三季度已累计回购超过 7.5 亿美元股份，结合常规年度分红，股东总回报率在港美股传媒板块中名列前茅。\n </p>\n </div>\n </div>\n </section>\n\n <!-- 01. 业务架构与收入演进 -->\n <section id=\"sec-biz\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-tmeblue-600 dark:text-tmeblue-400\">Section 01 · Business Architecture & Revenue Evolution</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">一、 业务架构与收入演进：订阅与演唱会双引擎狂飙，喜马拉雅并表拓宽音频版图</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">FY26E 总营收预计超 RMB 350亿 · 音乐订阅成绝对压舱石</span>\n </div>\n\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6\">\n <div class=\"lg:col-span-7 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-wrap items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\" id=\"biz-chart-title\">2023–2026E 在线音乐与社交娱乐收入结构演进 (亿元人民币)</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-0.5\" id=\"biz-chart-sub\">在线音乐订阅及 IP 消费收入占比持续攀升，成功对冲传统社交娱乐业务的结构性回调</p>\n </div>\n <div class=\"inline-flex rounded-lg bg-slate-100 dark:bg-navy-800 p-1 text-xs no-print\">\n <button onclick=\"switchBizChart('revenue_mix')\" id=\"btn-chart-mix\" class=\"px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-tmeblue-600 dark:text-tmeblue-400 shadow-sm transition cursor-pointer\">视图A：收入分部结构</button>\n <button onclick=\"switchBizChart('metrics_growth')\" id=\"btn-chart-metrics\" class=\"px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition cursor-pointer\">视图B：Q3 2026 核心指标拆解</button>\n </div>\n </div>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"bizArchitectureChart\"></canvas>\n </div>\n </div>\n\n <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">2026Q3 三大核心增长驱动力</h3>\n <ul class=\"space-y-4 text-sm\">\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-tmeblue-500/15 text-tmeblue-600 dark:text-tmeblue-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">1</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">音乐订阅收入达 RMB 49.9亿（+9.2% YoY），SVIP 渗透提速</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 得益于超级会员（SVIP）体系的持续扩张与高品质音效、独家数字专辑权益赋能，ARPPU（每付费用户平均收入）实现结构性增长，对冲了泛大众基础订阅增速的自然放缓。\n </p>\n </div>\n </li>\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">2</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">营销与消费服务同比暴增 +12.1% 至 RMB 27.0亿</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 依托与华语乐坛头部艺人的战略合作，成功操盘多场现象级大型线下演唱会巡演，并带动艺人官方正版实体周边与粉丝经济消费爆发，构筑第二成长曲线。\n </p>\n </div>\n </li>\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-tmeviolet-500/15 text-tmeviolet-600 dark:text-tmeviolet-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">3</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">喜马拉雅并表协同，长音频生态与内容库深度打通</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 随着喜马拉雅全面纳入合并报表（贡献单季数亿元稳健增量），TME 在长音频、播客及有声书领域的版权垄断力和跨场景分发优势达到历史巅峰。\n </p>\n </div>\n </li>\n </ul>\n </div>\n <div class=\"mt-5 pt-4 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-xs\">\n <span class=\"text-slate-500 dark:text-slate-400\">战略核心锚点</span>\n <span class=\"font-bold text-tmeblue-600 dark:text-tmeblue-400\">一体两翼：内容与平台双核驱动</span>\n </div>\n </div>\n </div>\n\n <div class=\"grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-5\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-tmeblue-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-3\">\n <span class=\"px-2.5 py-1 rounded-md bg-tmeblue-500/15 text-tmeblue-700 dark:text-tmeblue-400 text-xs font-bold\">核心现金牛 · 占总营收 ~55.8%</span>\n <span class=\"font-mono text-xs font-bold text-emerald-600 dark:text-emerald-400\">+9.2% YoY</span>\n </div>\n <h3 class=\"text-lg font-bold text-slate-900 dark:text-white\">1. 在线音乐订阅服务</h3>\n <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n Q3 订阅收入达 <strong>RMB 49.9亿元</strong>。通过腾讯生态（微信视频号、微信支付、QQ音乐及酷狗）的高效引流与 SVIP 高价值权益渗透，付费用户黏性与 ARPPU 保持双升。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-slate-500\">\n Q3 订阅收入 RMB 4.99B\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-emerald-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-3\">\n <span class=\"px-2.5 py-1 rounded-md bg-emerald-500/15 text-emerald-700 dark:text-emerald-400 text-xs font-bold\">高成长引擎 · 占总营收 ~30.2%</span>\n <span class=\"font-mono text-xs font-bold text-emerald-600 dark:text-emerald-400\">+12.1% YoY</span>\n </div>\n <h3 class=\"text-lg font-bold text-slate-900 dark:text-white\">2. 营销与消费类服务</h3>\n <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n Q3 收入达 <strong>RMB 27.0亿元</strong>。涵盖大型线下演唱会主办、艺人周边售卖及数字专辑销售，成为拉动总收入超预期增长的核心催化剂。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-slate-500\">\n Q3 消费服务 RMB 2.70B\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-amber-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-3\">\n <span class=\"px-2.5 py-1 rounded-md bg-amber-500/15 text-amber-700 dark:text-amber-400 text-xs font-bold\">战略转型期 · 占总营收 ~14.0%</span>\n <span class=\"font-mono text-xs font-bold text-rose-500\">-15.7% YoY</span>\n </div>\n <h3 class=\"text-lg font-bold text-slate-900 dark:text-white\">3. 社交娱乐及其他服务</h3>\n <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n Q3 收入降至 <strong>RMB 12.6亿元</strong>。受行业合规监管及直播互动娱乐竞争分流影响，该板块虽延续同比收缩，但下滑斜率已逐步趋缓，对集团整体盈利负面冲击减弱。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-slate-500\">\n Q3 社交娱乐 RMB 1.26B\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-tmeviolet-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-3\">\n <span class=\"px-2.5 py-1 rounded-md bg-tmeviolet-500/15 text-tmeviolet-700 dark:text-tmeviolet-400 text-xs font-bold\">重磅并表资产 · 音频新版图</span>\n <span class=\"font-mono text-xs font-bold text-tmeviolet-600 dark:text-tmeviolet-400\">深度协同</span>\n </div>\n <h3 class=\"text-lg font-bold text-slate-900 dark:text-white\">4. 喜马拉雅并表音频生态</h3>\n <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n 整合喜马拉雅全套播客、有声书与长音频内容库，不仅贡献稳健营收与会员权益交叉销售，更进一步构筑中国声音内容绝对统治地位。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-slate-500\">\n 全生态音频市占率领先\n </div>\n </div>\n </div>\n </section>\n\n <!-- 02. 版权壁垒与生态护城河 -->\n <section id=\"sec-moat\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-emerald-600 dark:text-emerald-400\">Section 02 · Copyright Moat & Ecosystem Advantage</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">二、 版权壁垒与生态护城河：腾讯社交帝国导流、AI DJ个性化与独家版权网络</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">护城河评级：极宽 (Wide Moat · 国内在线音乐绝对龙头)</span>\n </div>\n\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6 items-center\">\n <div class=\"lg:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-tmeblue-500/15 text-tmeblue-600 dark:text-tmeblue-400 flex items-center justify-center font-bold text-sm\">01</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">QQ音乐与酷狗音乐双超大流量基本盘</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 拥有国内最庞大的月活数字音乐用户群，结合腾讯微信生态（微信视频号一键分享、微信支付无缝续费、小程序轻量化点播），获客成本远低于任何互联网新进入者。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 flex items-center justify-center font-bold text-sm\">02</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">环球、索尼、华纳全球三大唱片深度绑定</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 与全球三大顶级唱片公司及国内数百家头部独立厂牌保持数十年独家及紧密转授权合作，构筑起中国市场上无可替代的超豪华正版音乐版权曲库高墙。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-tmeviolet-500/15 text-tmeviolet-600 dark:text-tmeviolet-400 flex items-center justify-center font-bold text-sm\">03</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">AI DJ 与生成式推荐算法赋能时长留存</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 推出升级版 AI DJ 智能助手，充当实时“个人DJ”根据用户听歌习惯动态生成个性化歌单；配合智能音效技术，显著推高核心付费用户的平台日均使用时长与留存率。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-sky-500/15 text-sky-600 dark:text-sky-400 flex items-center justify-center font-bold text-sm\">04</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">SVIP 会员体系与跨界联名生态变现</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 超级会员（SVIP）不仅享受最高音质与数字专辑特权，更深度打通热门游戏 IP（如《鸣潮》等联名装扮）及演出优先购票权，将单用户变现潜力挖掘到极致。\n </p>\n </div>\n </div>\n\n <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">腾讯音乐 vs 全球流媒体与文娱巨头五维能力雷达图</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">TME vs Spotify (SPOT) vs 网易云音乐 (Cloud Village)（满分 10 分）</p>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"moatRadarChart\"></canvas>\n </div>\n </div>\n </div>\n </section>\n\n <!-- 03. 全球流媒体与文娱横向对比 -->\n <section id=\"sec-comp\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-3\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-tmeblue-600 dark:text-tmeblue-400\">Section 03 · Global Music & Streaming Competitive Landscape</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">三、 全球音乐与流媒体巨头横向对比：高盈利质量、高现金储备与股东回报标杆</h2>\n </div>\n <div class=\"flex flex-wrap gap-1.5 text-xs no-print\" id=\"comp-filter-group\">\n <button onclick=\"filterCompetitors('all')\" data-filter=\"all\" class=\"comp-filter-btn active px-3 py-1.5 rounded-lg font-semibold bg-tmeblue-500 text-white shadow-sm transition cursor-pointer\">全部巨头</button>\n <button onclick=\"filterCompetitors('global')\" data-filter=\"global\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition cursor-pointer\">全球流媒体巨头</button>\n <button onclick=\"filterCompetitors('domestic')\" data-filter=\"domestic\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition cursor-pointer\">中国本土文娱对手</button>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden\">\n <div class=\"overflow-x-auto\">\n <table class=\"w-full text-left border-collapse\">\n <thead>\n <tr class=\"bg-slate-100/80 dark:bg-navy-800/80 border-b border-slate-200 dark:border-slate-700 text-xs font-bold uppercase tracking-wider text-slate-600 dark:text-slate-300\">\n <th class=\"py-4 px-5 min-w-[180px]\">企业名称与核心平台</th>\n <th class=\"py-4 px-4 min-w-[130px]\">核心市场覆盖</th>\n <th class=\"py-4 px-4 min-w-[140px]\">商业模式与增值亮点</th>\n <th class=\"py-4 px-4 min-w-[100px]\">远期 P/E</th>\n <th class=\"py-4 px-4 min-w-[115px]\">股息率 / 回购率</th>\n <th class=\"py-4 px-4 min-w-[115px]\">净利润率</th>\n <th class=\"py-4 px-5 min-w-[230px]\">核心优劣势与资本定位评估</th>\n </tr>\n </thead>\n <tbody class=\"divide-y divide-slate-200 dark:divide-slate-800 text-xs sm:text-sm\" id=\"comp-table-body\">\n <tr data-category=\"core\" class=\"bg-tmeblue-500/5 dark:bg-tmeblue-500/10 font-medium\">\n <td class=\"py-4 px-5\">\n <div class=\"flex items-center space-x-2\">\n <span class=\"px-2 py-0.5 rounded bg-tmeblue-500 text-white text-[10px] font-extrabold\">核心标的</span>\n <span class=\"font-bold text-slate-900 dark:text-white\">腾讯音乐 (TME)</span>\n </div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">QQ音乐 / 酷狗 / 喜马拉雅</div>\n </td>\n <td class=\"py-4 px-4 font-semibold text-slate-900 dark:text-white\">中国大陆主导地位</td>\n <td class=\"py-4 px-4\">\n <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-semibold bg-tmeblue-500/15 text-tmeblue-700 dark:text-tmeblue-400\">SVIP会员 + 演唱会IP</span>\n </td>\n <td class=\"py-4 px-4 font-mono font-bold text-slate-900 dark:text-white\">~10.4x</td>\n <td class=\"py-4 px-4 font-mono font-bold text-sky-600 dark:text-sky-400\">~2.7% + 密集回购</td>\n <td class=\"py-4 px-4 font-mono font-bold text-emerald-600 dark:text-emerald-400\">~27.5%</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>高现金流与SVIP驱动利润红利：</strong>手握 RMB 515亿巨额现金，前三季度回购超 $7亿，ARPPU 提升与喜马拉雅并表释放极强盈利韧性。\n </td>\n </tr>\n\n <tr data-category=\"global\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n <td class=\"py-4 px-5\">\n <div class=\"font-bold text-slate-900 dark:text-white\">Spotify (SPOT)</div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">Spotify Premium / Podcasters</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">全球欧美及拉美市场</td>\n <td class=\"py-4 px-4\">\n <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-semibold bg-emerald-500/15 text-emerald-700 dark:text-emerald-400\">全球付费订阅巨头</span>\n </td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~35.0x+</td>\n <td class=\"py-4 px-4 font-mono text-slate-500 dark:text-slate-400\">0% (无分红/轻回购)</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~8.5%</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>全球化龙头但估值高企：</strong>拥有庞大全球 MAU，但受制于高昂的海外版权成本，净利润率远低于 TME，估值倍数较高。\n </td>\n </tr>\n\n <tr data-category=\"domestic\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n <td class=\"py-4 px-5\">\n <div class=\"font-bold text-slate-900 dark:text-white\">网易云音乐 (Cloud Village)</div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">网易云音乐 / LOOK直播</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">中国年轻世代音乐用户</td>\n <td class=\"py-4 px-4\">\n <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-amber-500/15 text-amber-700 dark:text-amber-400\">社区氛围与独立音乐人</span>\n </td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~14.0x</td>\n <td class=\"py-4 px-4 font-mono text-slate-500 dark:text-slate-400\">较低</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~12.0%</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>年轻社区差异化竞争：</strong>在独立音乐人和评论区社区文化上具备特色，但总体曲库广度与 ARPPU 变现能力落后于 TME。\n </td>\n </tr>\n\n <tr data-category=\"global\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n <td class=\"py-4 px-5\">\n <div class=\"font-bold text-slate-900 dark:text-white\">苹果 Apple Music / YouTube Music</div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">Apple Ecosystem / Google Play</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">全球高端硬件生态用户</td>\n <td class=\"py-4 px-4\">\n <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-sky-500/15 text-sky-700 dark:text-sky-400\">硬件捆绑生态服务</span>\n </td>\n <td class=\"py-4 px-4 font-mono text-slate-500 dark:text-slate-400\">作为巨头子业务</td>\n <td class=\"py-4 px-4 font-mono text-slate-500 dark:text-slate-400\">N/A</td>\n <td class=\"py-4 px-4 font-mono text-slate-500 dark:text-slate-400\">高 (综合体)</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>生态捆绑巨兽：</strong>利用硬件生态自带高粘性用户，不以单一音乐流媒体盈利为首要目标，对独立流媒体形成长期跨界压制。\n </td>\n </tr>\n </tbody>\n </table>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">全球主要音乐流媒体平台净利润率 (Net Profit Margin) 与估值对比</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400\">腾讯音乐凭借高毛利订阅与精细化运营，净利润率与资本回报表现领先全行业</p>\n </div>\n <span class=\"text-xs font-semibold text-tmeblue-700 dark:text-tmeblue-400 bg-tmeblue-500/15 px-2.5 py-1 rounded\">~27.5% 净利润率效率领先</span>\n </div>\n <div class=\"relative h-64 w-full\">\n <canvas id=\"compMarginChart\"></canvas>\n </div>\n </div>\n </section>\n\n <!-- 04. 财务健康与回购复利模型 -->\n <section id=\"sec-fin\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-emerald-600 dark:text-emerald-400\">Section 04 | Financial Health & Buyback Compounding Model</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">四、 财务健康与股东回报：515亿现金堡垒与“回购注销+稳定分红”复利引擎</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">零有息负债压力 · 前三季度回购超 $7.0亿</span>\n </div>\n\n <div class=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-tmeblue-600 dark:text-tmeblue-400 uppercase\">Gross Margin</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">~42.8%</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 尽管因低毛利 IP 演唱会周边及喜马拉雅并表结构性微调，整体毛利率依然稳在 43% 左右，高价值音乐订阅占比持续提升。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 uppercase\">Cash & Short-Term Assets</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">RMB 51.5B</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 现金、定期存款及短期投资总额达 514.9 亿元人民币（约合 75 亿美元），占公司当前总市值比例超 65%，安全垫极其厚实。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-tmeviolet-600 dark:text-tmeviolet-400 uppercase\">Share Buyback Pace</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">&gt;$700M (YTD)</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n Q3 单季在公开市场回购 3,470 万股 ADS（耗资约 $3.0亿），此前 Q2 亦回购 $4.0亿，强力缩减总股本并增厚每股收益。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-sky-600 dark:text-sky-400 uppercase\">Net Profit Margin</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">~27.5%</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 严格的费用管控和高利润率音乐订阅驱动下，非国际财务报告准则净利润率保持在近 28% 的行业极高水平。\n </p>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">2023–2026E 调整后净利润增长 vs 流通总股本持续注销缩减趋势</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400\">通过持续的大额公开市场回购注销，TME 流通 ADS 数量稳步收缩，强力推动每股盈利（EPS）实现超越总利润的复利增长</p>\n </div>\n <span class=\"text-xs font-mono font-bold text-tmeblue-700 dark:text-tmeblue-400 bg-tmeblue-500/15 px-2.5 py-1 rounded\">年化回购兑现每股增厚</span>\n </div>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"valEvolutionChart\"></canvas>\n </div>\n </div>\n\n <!-- 互动推演器 -->\n <div class=\"bg-gradient-to-br from-navy-900 via-navy-800 to-slate-900 rounded-2xl p-6 sm:p-8 text-white border border-slate-700 shadow-xl space-y-6 no-print\">\n <div class=\"flex flex-col md:flex-row md:items-center justify-between gap-3 pb-4 border-b border-slate-700/80\">\n <div>\n <div class=\"inline-flex items-center space-x-2 text-xs font-mono uppercase tracking-wider text-sky-400 font-bold\">\n <span>TME LONG-TERM COMPOUNDING SIMULATOR · 腾讯音乐长线复利测算器</span>\n </div>\n <h3 class=\"text-lg sm:text-xl font-bold text-white mt-1\">TME 股东回报与 DRIP 复利动态推演器</h3>\n <p class=\"text-xs text-slate-400 mt-0.5\">基准参数：当前股价 $9.15 | 预计年化净利增长 8.0% | 支持不同税务及分红再投资情景测算</p>\n </div>\n <label class=\"inline-flex items-center space-x-2.5 px-3.5 py-2 rounded-xl bg-tmeblue-500/15 border border-tmeblue-400/30 text-xs font-semibold text-sky-300 cursor-pointer shrink-0\">\n <input type=\"checkbox\" id=\"drip-toggle\" checked onchange=\"updateDividendSimulator()\" class=\"w-4 h-4 rounded accent-[#0284C7] cursor-pointer\">\n <span>开启股息自动再投资 (DRIP)</span>\n </label>\n </div>\n\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6 items-center\">\n <div class=\"lg:col-span-5 space-y-4 text-xs\">\n <div>\n <div class=\"flex justify-between mb-1.5\">\n <span class=\"text-slate-300 font-medium\">初始投入本金 (USD)</span>\n <span id=\"sim-principal-label\" class=\"font-mono font-bold text-white text-sm\">$30,000</span>\n </div>\n <input id=\"sim-principal\" type=\"range\" min=\"5000\" max=\"200000\" step=\"5000\" value=\"30000\" oninput=\"updateDividendSimulator()\" class=\"w-full accent-[#0284C7] cursor-pointer\">\n </div>\n\n <div>\n <div class=\"flex justify-between mb-1.5\">\n <span class=\"text-slate-300 font-medium\">长期持有年限 (Years)</span>\n <span id=\"sim-years-label\" class=\"font-mono font-bold text-white text-sm\">10 年</span>\n </div>\n <input id=\"sim-years\" type=\"range\" min=\"1\" max=\"20\" step=\"1\" value=\"10\" oninput=\"updateDividendSimulator()\" class=\"w-full accent-[#0284C7] cursor-pointer\">\n </div>\n\n <div>\n <div class=\"flex justify-between mb-1.5\">\n <span class=\"text-slate-300 font-medium\">年均业绩与股价增长率</span>\n <span id=\"sim-growth-label\" class=\"font-mono font-bold text-emerald-400 text-sm\">8.0%</span>\n </div>\n <input id=\"sim-growth\" type=\"range\" min=\"0\" max=\"15\" step=\"0.5\" value=\"8.0\" oninput=\"updateDividendSimulator()\" class=\"w-full accent-[#10B981] cursor-pointer\">\n </div>\n\n <div class=\"pt-1\">\n <div class=\"text-slate-300 font-medium mb-2\">美股 ADR 股息预扣税率情景：</div>\n <div class=\"grid grid-cols-3 gap-2\" id=\"tax-btn-group\">\n <button type=\"button\" onclick=\"setTaxRate(0)\" data-tax=\"0\" class=\"tax-btn px-2 py-2 rounded-lg text-[11px] font-medium bg-navy-950/70 text-slate-300 border border-slate-700 hover:border-sky-400 transition cursor-pointer\">\n 0% 免税账户<br><span class=\"text-[10px] text-slate-400\">海外/退休账户</span>\n </button>\n <button type=\"button\" onclick=\"setTaxRate(0.10)\" data-tax=\"0.1\" class=\"tax-btn active px-2 py-2 rounded-lg text-[11px] font-bold bg-tmeblue-500 text-white border border-sky-400 shadow transition cursor-pointer\">\n 10% 协定税率<br><span class=\"text-[10px] text-sky-200\">中美税收协定</span>\n </button>\n <button type=\"button\" onclick=\"setTaxRate(0.30)\" data-tax=\"0.3\" class=\"tax-btn px-2 py-2 rounded-lg text-[11px] font-medium bg-navy-950/70 text-slate-300 border border-slate-700 hover:border-sky-400 transition cursor-pointer\">\n 30% 标准预扣<br><span class=\"text-[10px] text-slate-400\">特定海外地区</span>\n </button>\n </div>\n </div>\n </div>\n\n <div class=\"lg:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-4\">\n <div class=\"bg-navy-950/80 rounded-xl p-5 border border-slate-800\">\n <div class=\"text-xs text-slate-400\">期末预计总资产 (含分红)</div>\n <div id=\"sim-final-value\" class=\"text-2xl sm:text-3xl font-mono font-extrabold text-white mt-1.5\">$78,450</div>\n <div id=\"sim-total-return\" class=\"text-xs font-semibold text-emerald-400 mt-1.5\">累计总回报 +161.5%</div>\n </div>\n\n <div class=\"bg-navy-950/80 rounded-xl p-5 border border-slate-800\">\n <div class=\"text-xs text-slate-400\">期末年度税后现金分红</div>\n <div id=\"sim-annual-div\" class=\"text-2xl sm:text-3xl font-mono font-extrabold text-sky-400 mt-1.5\">$2,410</div>\n <div id=\"sim-monthly-div\" class=\"text-xs text-slate-400 mt-1.5\">折合每月被动现金流 ~$201</div>\n </div>\n\n <div class=\"bg-navy-950/80 rounded-xl p-5 border border-slate-800\">\n <div class=\"text-xs text-slate-400\">期末税后成本股息率 (Yield on Cost)</div>\n <div id=\"sim-yoc\" class=\"text-2xl sm:text-3xl font-mono font-extrabold text-teal-400 mt-1.5\">8.03%</div>\n <div class=\"text-xs text-slate-400 mt-1.5\">相对于初始投入本金的分红回报率</div>\n </div>\n\n <div class=\"bg-navy-950/80 rounded-xl p-5 border border-slate-800\">\n <div class=\"text-xs text-slate-400\">持有期累计获配税后股息总额</div>\n <div id=\"sim-cum-div\" class=\"text-2xl sm:text-3xl font-mono font-extrabold text-emerald-400 mt-1.5\">$16,820</div>\n <div id=\"sim-shares-end\" class=\"text-xs text-slate-400 mt-1.5\">期末持仓股数：3,580 股 (起始 3,278 股)</div>\n </div>\n </div>\n </div>\n </div>\n </section>\n\n <!-- 05. 投资决策与风险配置 -->\n <section id=\"sec-inv\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-tmeblue-600 dark:text-tmeblue-400\">Section 05 | Investment Decision & Risk Valuation</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">五、 投资决策与风险配置：三情景估值推演与文娱资产配置框架</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">配置建议：逢回调积极布局 · 10x P/E 具备极高安全边际</span>\n </div>\n\n <div class=\"grid grid-cols-1 md:grid-cols-3 gap-5\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-emerald-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 text-xs font-bold\">牛市情景 (Bull Case)</span>\n <span class=\"font-mono text-xs font-bold text-emerald-600 dark:text-emerald-400\">概率：25%</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">14.0x–16.0x P/E ($13–$15)</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心假设：</strong>付费用户ARPPU加速提升，SVIP渗透率超出预期；喜马拉雅并表协同效应全面爆发，线下演出及周边市场持续火爆，海外广告及流媒体估值溢价修复。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-emerald-600 dark:text-emerald-400\">\n 潜在回报空间：+40% 至 +65%\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-tmeblue-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-tmeblue-500/15 text-tmeblue-700 dark:text-tmeblue-400 text-xs font-bold\">基准情景 (Base Case)</span>\n <span class=\"font-mono text-xs font-bold text-tmeblue-600 dark:text-tmeblue-400\">概率：55%</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">11.0x–13.0x P/E ($10–$11.5)</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心假设：</strong>音乐订阅稳健增长（高个位数），社交娱乐业务下滑逐季收窄企稳，公司延续每年超 7 亿美元的回购与常规分红强度，估值中枢向 12x P/E 合理靠拢。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-tmeblue-600 dark:text-tmeblue-400\">\n 稳健回报空间：+15% 至 +25% (含分红回购)\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-rose-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-rose-500/15 text-rose-600 dark:text-rose-400 text-xs font-bold\">熊市情景 (Bear Case)</span>\n <span class=\"font-mono text-xs font-bold text-rose-600 dark:text-rose-400\">概率：20%</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">8.0x–9.5x P/E ($7.5–$8.5)</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心假设：</strong>宏观消费疲软导致在线音乐付费用户净增放缓，社交娱乐下滑超预期，版权成本或宣发费用刚性上涨压制毛利率。巨额现金底座构成坚实估值底部。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-rose-600 dark:text-rose-400\">\n 潜在回撤风险：-10% 至 -18% (现金底座构筑强支撑)\n </div>\n </div>\n </div>\n\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">四大核心潜在风险评估与跟踪边界</h3>\n <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2 py-0.5 rounded bg-rose-500/10 text-rose-600 dark:text-rose-400 text-xs font-bold\">01 · 宏观消费波动与付费意愿放缓</span>\n <span class=\"text-xs font-mono text-rose-500 font-semibold\">关注度：高</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">大众付费意愿与 ARPPU 提升斜率承压</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 若居民可支配收入增速放缓，可能对 SVIP 高阶会员的续费率及扩展速度产生扰动，影响订阅收入增速。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2 py-0.5 rounded bg-amber-500/10 text-amber-600 dark:text-amber-400 text-xs font-bold\">02 · 社交娱乐收入持续下行压力</span>\n <span class=\"text-xs font-mono text-amber-500 font-semibold\">关注度：中高</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">直播与泛娱乐互动面临外部短视频分流</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 社交娱乐服务占比较高时期的下滑惯性若未能如期触底，将对整体营收增速形成一定拖累。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2 py-0.5 rounded bg-tmeblue-500/10 text-tmeblue-600 dark:text-tmeblue-400 text-xs font-bold\">03 · 版权成本续签与向上波动风险</span>\n <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：中</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">与各大唱片公司长期版权协议续约条款</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 随着国内音乐版权竞争格局演变，头部版权采购成本若出现非理性上涨，将对毛利率改善构成扰动。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2 py-0.5 rounded bg-indigo-500/10 text-indigo-600 dark:text-indigo-400 text-xs font-bold\">04 · 喜马拉雅整合进度与商誉减值考量</span>\n <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：中</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">新并购资产协同效应与财务摊销</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 喜马拉雅并表带来的管理整合、业务交叉打通以及后续采购摊销需持续追踪其实际业绩兑现情况。\n </p>\n </div>\n </div>\n </div>\n\n <div class=\"bg-gradient-to-r from-navy-900 to-navy-800 rounded-2xl p-6 text-white border border-slate-700 shadow-md\">\n <h3 class=\"text-base font-bold text-sky-400 mb-4 flex items-center space-x-2\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n <span>机构级投资组合配置纪律与策略建议</span>\n </h3>\n <div class=\"grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n <div class=\"font-bold text-white mb-1\">1. 高现金底座与防御配置价值</div>\n <p class=\"text-slate-300 leading-relaxed\">\n 鉴于 RMB 515 亿现金及短期投资（占市值超 65%）构成的极强安全垫，TME 在港美股科技板块中具备极高的抗波动防御与价值回归属性。\n </p>\n </div>\n <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n <div class=\"font-bold text-sky-400 mb-1\">2. 估值锚点与分批增配策略</div>\n <p class=\"text-slate-300 leading-relaxed\">\n 当前 Forward P/E 仅 ~10.4x，处于历史估值中枢偏下区间。建议作为中国数字文娱核心标的长期底仓持有，逢市场回调积极增配。\n </p>\n </div>\n <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n <div class=\"font-bold text-emerald-400 mb-1\">3. 回购与分红红利兑现</div>\n <p class=\"text-slate-300 leading-relaxed\">\n 密切追踪管理层每季度公开市场股份回购执行力度及年度分红政策，充分享受流通股缩减带来的每股收益内生增长红利。\n </p>\n </div>\n </div>\n </div>\n </section>\n\n <!-- 06. 季度跟踪 KPI 交互式核查清单 -->\n <section id=\"sec-kpi\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-emerald-600 dark:text-emerald-400\">Section 06 | Quarterly Fundamental Tracking KPIs</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">六、 季度基本面跟踪 KPI 交互式核查清单（Checklist）</h2>\n </div>\n <div class=\"flex items-center space-x-2 no-print\">\n <span id=\"kpi-progress-badge\" class=\"px-3 py-1 rounded-full bg-tmeblue-500/15 text-tmeblue-700 dark:text-tmeblue-400 text-xs font-bold\">已核查 3 / 6 项 (50%)</span>\n <button onclick=\"resetKpiChecklist()\" class=\"px-2.5 py-1 rounded-lg bg-slate-200/80 dark:bg-navy-800 hover:bg-slate-300 dark:hover:bg-navy-700 text-xs font-medium text-slate-700 dark:text-slate-300 transition cursor-pointer\">重置清单</button>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">\n 点击勾选季度财报中已验证达标的经营指标（勾选状态自动本地保存），持续检验腾讯音乐付费转化与股东回报长牛逻辑：\n </p>\n\n <div class=\"grid grid-cols-1 md:grid-cols-2 gap-3.5\" id=\"kpi-checklist\">\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-1\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0284C7]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">1. 在线音乐订阅收入保持高个位数至双位数同比稳健增长</span>\n <span class=\"text-[11px] font-mono text-tmeblue-600 dark:text-tmeblue-400 font-semibold shrink-0\">核心订阅锚</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 2026Q3 订阅收入达 49.9 亿元（+9.2% YoY），需持续验证 ARPPU 与 SVIP 付费用户的扩张势头。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-1\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0284C7]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">2. SVIP（超级会员）渗透率与人均消费额（ARPPU）持续提升</span>\n <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">高阶变现引擎</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 关注 SVIP 用户在平台总付费用户中的占比以及高音质、独家定制权益带来的 ARPU 增厚效应。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-3\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0284C7]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">3. 营销与消费服务（演唱会与周边）保持双位数同比高增</span>\n <span class=\"text-[11px] font-mono text-tmeviolet-600 dark:text-tmeviolet-400 font-semibold shrink-0\">第二增长曲线</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n Q3 消费服务大增 12.1% 至 27.0 亿元；需追踪线下演出排期及粉丝经济周边变现的持续性。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-4\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0284C7]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">4. 喜马拉雅并表后的协同效应与音频生态盈利贡献</span>\n <span class=\"text-[11px] font-mono text-sky-600 dark:text-sky-400 font-semibold shrink-0\">并购整合指标</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 评估长音频与音乐会员权益交叉打通后的用户活跃度、流量转化率及毛利率平稳表现。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-5\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0284C7]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">5. 社交娱乐服务下滑幅度是否逐季收窄并企稳触底</span>\n <span class=\"text-[11px] font-mono text-amber-600 dark:text-amber-400 font-semibold shrink-0\">风险监测锚</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 监控社交娱乐及其他板块同比降幅（Q3 为 -15.7%）是否趋于平缓，减少对整体大盘的拖累。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-6\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0284C7]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">6. 每季度公开市场股份回购执行力度与现金储备安全边界</span>\n <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">股东回报放大器</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 确认公司现金及短期资产保持在 500 亿元人民币高位，并按计划推进每季度亿美元级别的 ADS 回购注销。\n </p>\n </div>\n </label>\n </div>\n </div>\n </section>\n\n <footer class=\"pt-8 border-t border-slate-200 dark:border-slate-800 text-xs text-slate-500 dark:text-slate-400 space-y-2 pb-10\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 font-semibold text-slate-700 dark:text-slate-300\">\n <span>腾讯音乐娱乐集团 Tencent Music Entertainment Group (NYSE: TME) 深度商业与投资价值分析报告</span>\n <span>数据基准：2026Q3 财报及 2026 年 11 月市场一致预期 (FY26E)</span>\n </div>\n <p class=\"leading-relaxed\">\n <strong>免责声明：</strong>本深度研究报告基于腾讯音乐娱乐集团公开财务报告（20-F/6-K）、2026Q3 业绩公告及全球数字流媒体行业调研资料整理生成，旨在提供结构化的产业分析与文娱资产估值框架。报告中涉及的盈利预测、回购测算、三情景目标价及 DRIP 复利模拟均基于特定假设条件推演，不构成任何证券买卖建议、税务规划意见或收益承诺。美股 ADR 股息预扣税率因投资者国籍及账户属性存在差异，请在独立核实后审慎决策。\n </p>\n </footer>\n\n </div>\n </main>\n\n <script>\n function toggleTheme() {\n const html = document.documentElement;\n html.classList.toggle('dark');\n updateChartsTheme();\n }\n\n function toggleMobileMenu() {\n const drawer = document.getElementById('mobile-drawer');\n drawer.classList.toggle('hidden');\n }\n\n const sections = document.querySelectorAll('section[id]');\n const navLinks = document.querySelectorAll('#desktop-nav .nav-link');\n\n window.addEventListener('scroll', () => {\n const scrollTop = window.scrollY;\n const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n const scrollPercent = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0;\n document.getElementById('reading-progress').style.width = `${Math.min(100, Math.max(0, scrollPercent))}%`;\n\n let currentId = 'sec-exec';\n sections.forEach(sec => {\n const top = sec.offsetTop - 160;\n if (scrollTop >= top) {\n currentId = sec.getAttribute('id');\n }\n });\n\n navLinks.forEach(link => {\n link.classList.remove('active');\n const numSpan = link.querySelector('span span');\n if (numSpan) {\n numSpan.classList.remove('text-sky-400');\n numSpan.classList.add('text-slate-500');\n }\n if (link.dataset.target === currentId) {\n link.classList.add('active');\n if (numSpan) {\n numSpan.classList.remove('text-slate-500');\n numSpan.classList.add('text-sky-400');\n }\n }\n });\n });\n\n function filterCompetitors(category) {\n document.querySelectorAll('.comp-filter-btn').forEach(btn => {\n if (btn.dataset.filter === category) {\n btn.classList.add('bg-tmeblue-500', 'text-white', 'font-semibold', 'shadow-sm');\n btn.classList.remove('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n } else {\n btn.classList.remove('bg-tmeblue-500', 'text-white', 'font-semibold', 'shadow-sm');\n btn.classList.add('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n }\n });\n\n const rows = document.querySelectorAll('#comp-table-body tr');\n rows.forEach(row => {\n const rowCat = row.dataset.category;\n if (category === 'all' || rowCat === 'core' || rowCat === category) {\n row.style.display = '';\n } else {\n row.style.display = 'none';\n }\n });\n }\n\n let currentTaxRate = 0.10;\n\n function setTaxRate(rate) {\n currentTaxRate = rate;\n document.querySelectorAll('#tax-btn-group .tax-btn').forEach(btn => {\n const btnRate = parseFloat(btn.dataset.tax);\n if (Math.abs(btnRate - rate) < 0.001) {\n btn.className = 'tax-btn active px-2 py-2 rounded-lg text-[11px] font-bold bg-tmeblue-500 text-white border border-sky-400 shadow transition cursor-pointer';\n const subSpan = btn.querySelector('span');\n if (subSpan) subSpan.className = 'text-[10px] text-sky-200';\n } else {\n btn.className = 'tax-btn px-2 py-2 rounded-lg text-[11px] font-medium bg-navy-950/70 text-slate-300 border border-slate-700 hover:border-sky-400 transition cursor-pointer';\n const subSpan = btn.querySelector('span');\n if (subSpan) subSpan.className = 'text-[10px] text-slate-400';\n }\n });\n updateDividendSimulator();\n }\n\n function updateDividendSimulator() {\n const principal = parseFloat(document.getElementById('sim-principal').value);\n const years = parseInt(document.getElementById('sim-years').value, 10);\n const growthPct = parseFloat(document.getElementById('sim-growth').value);\n const drip = document.getElementById('drip-toggle').checked;\n\n document.getElementById('sim-principal-label').textContent = '$' + principal.toLocaleString('en-US');\n document.getElementById('sim-years-label').textContent = years + ' 年';\n document.getElementById('sim-growth-label').textContent = growthPct.toFixed(1) + '%';\n\n const initPrice = 9.15;\n const initDps = 0.25;\n const g = growthPct / 100;\n\n const initialShares = principal / initPrice;\n let shares = initialShares;\n let sharePrice = initPrice;\n let dps = initDps;\n let cashPool = 0;\n let cumulativeNetDiv = 0;\n\n for (let y = 1; y <= years; y++) {\n const grossDiv = shares * dps;\n const netDiv = grossDiv * (1 - currentTaxRate);\n cumulativeNetDiv += netDiv;\n\n const nextPrice = sharePrice * (1 + g);\n if (drip) {\n const avgReinvestPrice = (sharePrice + nextPrice) / 2;\n shares += netDiv / avgReinvestPrice;\n } else {\n cashPool += netDiv;\n }\n sharePrice = nextPrice;\n if (y < years) {\n dps = dps * (1 + g);\n }\n }\n\n const endForwardDps = initDps * Math.pow(1 + g, years);\n const endAnnualNetDiv = shares * endForwardDps * (1 - currentTaxRate);\n const finalPortfolioVal = (shares * sharePrice) + cashPool;\n const totalReturnPct = ((finalPortfolioVal - principal) / principal) * 100;\n const yieldOnCost = (endAnnualNetDiv / principal) * 100;\n\n document.getElementById('sim-final-value').textContent = '$' + Math.round(finalPortfolioVal).toLocaleString('en-US');\n document.getElementById('sim-total-return').textContent = `累计总回报 +${totalReturnPct.toFixed(1)}% (${drip ? '含DRIP复利' : '现金分红留存'})`;\n document.getElementById('sim-annual-div').textContent = '$' + Math.round(endAnnualNetDiv).toLocaleString('en-US');\n document.getElementById('sim-monthly-div').textContent = `折合每月税后被动现金流 ~$${Math.round(endAnnualNetDiv / 12).toLocaleString('en-US')}`;\n document.getElementById('sim-yoc').textContent = yieldOnCost.toFixed(2) + '%';\n document.getElementById('sim-cum-div').textContent = '$' + Math.round(cumulativeNetDiv).toLocaleString('en-US');\n document.getElementById('sim-shares-end').textContent = `期末持仓股数：${Math.round(shares).toLocaleString('en-US')} 股 (起始 ${Math.round(initialShares).toLocaleString('en-US')} 股)`;\n }\n\n const KPI_STORAGE_KEY = 'tme_research_kpi_state_v1';\n\n function loadKpiChecklist() {\n try {\n const saved = localStorage.getItem(KPI_STORAGE_KEY);\n if (saved) {\n const stateMap = JSON.parse(saved);\n document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n if (typeof stateMap[cb.id] === 'boolean') {\n cb.checked = stateMap[cb.id];\n }\n });\n }\n } catch (e) {}\n updateKpiChecklist();\n }\n\n function updateKpiChecklist() {\n const checkboxes = document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]');\n const total = checkboxes.length;\n let checkedCount = 0;\n const stateMap = {};\n\n checkboxes.forEach(cb => {\n stateMap[cb.id] = cb.checked;\n if (cb.checked) checkedCount++;\n });\n\n const pct = Math.round((checkedCount / total) * 100);\n document.getElementById('kpi-progress-badge').textContent = `已核查 ${checkedCount} / ${total} 项 (${pct}%)`;\n\n try {\n localStorage.setItem(KPI_STORAGE_KEY, JSON.stringify(stateMap));\n } catch (e) {}\n }\n\n function resetKpiChecklist() {\n document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n cb.checked = false;\n });\n updateKpiChecklist();\n }\n\n let bizChartInstance = null;\n let radarChartInstance = null;\n let compMarginChartInstance = null;\n let valEvolutionChartInstance = null;\n let currentBizMode = 'revenue_mix';\n\n function getChartColors() {\n const isDark = document.documentElement.classList.contains('dark');\n return {\n text: isDark ? '#CBD5E1' : '#475569',\n grid: isDark ? 'rgba(51, 65, 85, 0.5)' : 'rgba(226, 232, 240, 0.85)',\n radarAngle: isDark ? 'rgba(71, 85, 105, 0.6)' : 'rgba(203, 213, 225, 0.85)'\n };\n }\n\n function initBizChart() {\n const ctx = document.getElementById('bizArchitectureChart').getContext('2d');\n const colors = getChartColors();\n\n const mixConfig = {\n type: 'bar',\n data: {\n labels: ['2023', '2024', '2025', '2026E'],\n datasets: [\n {\n label: '在线音乐订阅收入 (亿元)',\n data: [102.2, 145.5, 182.0, 198.5],\n backgroundColor: '#0284C7',\n borderRadius: 4,\n stack: 'rev'\n },\n {\n label: '营销与消费服务收入 (亿元)',\n data: [55.4, 78.2, 95.0, 108.0],\n backgroundColor: '#10B981',\n borderRadius: 4,\n stack: 'rev'\n },\n {\n label: '社交娱乐及其他收入 (亿元)',\n data: [122.4, 88.0, 62.0, 52.5],\n backgroundColor: '#F59E0B',\n borderRadius: 4,\n stack: 'rev'\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n },\n tooltip: {\n callbacks: {\n label: (ctx) => `${ctx.dataset.label}: RMB ${ctx.parsed.y.toFixed(1)}亿`\n }\n }\n },\n scales: {\n x: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n },\n y: {\n min: 0,\n max: 360,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => ' RMB ' + v + '亿' }\n }\n }\n }\n };\n\n const metricsConfig = {\n type: 'bar',\n data: {\n labels: [\n 'Q3 音乐订阅收入同比增速 (+9.2%)',\n 'Q3 营销与消费服务同比增速 (+12.1%)',\n 'Q3 非IFRS净利润同比增速 (+2.1%)',\n 'Q3 社交娱乐服务同比变动 (-15.7%)',\n '现金及短期投资规模 (亿元)'\n ],\n datasets: [\n {\n label: '2026Q3 核心财务指标表现',\n data: [9.2, 12.1, 2.1, -15.7, 514.9],\n backgroundColor: ['#0284C7', '#10B981', '#8B5CF6', '#F43F5E', '#0369A1'],\n borderRadius: 6,\n barThickness: 22\n }\n ]\n },\n options: {\n indexAxis: 'y',\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: { display: false },\n tooltip: {\n callbacks: {\n label: (ctx) => `指标数值: ${ctx.parsed.x > 0 && ctx.dataIndex !== 4 ? '+' : ''}${ctx.parsed.x}${ctx.dataIndex === 4 ? '亿元' : '%'}`\n }\n }\n },\n scales: {\n x: {\n min: -20,\n max: 550,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 } }\n },\n y: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n };\n\n if (bizChartInstance) bizChartInstance.destroy();\n bizChartInstance = new Chart(ctx, currentBizMode === 'revenue_mix' ? mixConfig : metricsConfig);\n }\n\n function switchBizChart(mode) {\n currentBizMode = mode;\n const btnMix = document.getElementById('btn-chart-mix');\n const btnMetrics = document.getElementById('btn-chart-metrics');\n const titleEl = document.getElementById('biz-chart-title');\n const subEl = document.getElementById('biz-chart-sub');\n\n if (mode === 'revenue_mix') {\n btnMix.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-tmeblue-600 dark:text-tmeblue-400 shadow-sm transition cursor-pointer';\n btnMetrics.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition cursor-pointer';\n titleEl.textContent = '2023–2026E 在线音乐与社交娱乐收入结构演进 (亿元人民币)';\n subEl.textContent = '在线音乐订阅及 IP 消费收入占比持续攀升，成功对冲传统社交娱乐业务的结构性回调';\n } else {\n btnMetrics.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-tmeblue-600 dark:text-tmeblue-400 shadow-sm transition cursor-pointer';\n btnMix.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition cursor-pointer';\n titleEl.textContent = '2026Q3 核心财务与业务指标增长拆解';\n subEl.textContent = '订阅与演唱会消费保持双位数双引擎驱动，非IFRS净利保持正增长，现金资产突破 514 亿元';\n }\n initBizChart();\n }\n\n function initRadarChart() {\n const ctx = document.getElementById('moatRadarChart').getContext('2d');\n const colors = getChartColors();\n\n if (radarChartInstance) radarChartInstance.destroy();\n radarChartInstance = new Chart(ctx, {\n type: 'radar',\n data: {\n labels: [\n '中国本土用户生态与导流',\n '正版版权与唱片厂牌深度',\n '商业化毛利与净利率效率',\n '现金储备与股东回报力度',\n '全球化出海与海外拓展'\n ],\n datasets: [\n {\n label: '腾讯音乐 (TME)',\n data: [9.8, 9.7, 9.2, 9.6, 6.0],\n borderColor: '#0284C7',\n backgroundColor: 'rgba(2, 132, 199, 0.24)',\n pointBackgroundColor: '#0284C7',\n borderWidth: 2.5\n },\n {\n label: 'Spotify (SPOT)',\n data: [8.5, 9.0, 6.5, 5.0, 9.8],\n borderColor: '#10B981',\n backgroundColor: 'rgba(16, 185, 129, 0.14)',\n pointBackgroundColor: '#10B981',\n borderWidth: 2.0\n },\n {\n label: '网易云音乐 (Cloud Village)',\n data: [8.0, 7.8, 7.5, 6.5, 5.5],\n borderColor: '#8B5CF6',\n backgroundColor: 'rgba(139, 92, 246, 0.12)',\n pointBackgroundColor: '#8B5CF6',\n borderWidth: 1.8,\n borderDash: [4, 4]\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n }\n },\n scales: {\n r: {\n min: 0,\n max: 10,\n ticks: { display: false, stepSize: 2 },\n grid: { color: colors.grid },\n angleLines: { color: colors.radarAngle },\n pointLabels: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n });\n }\n\n function initCompMarginChart() {\n const ctx = document.getElementById('compMarginChart').getContext('2d');\n const colors = getChartColors();\n\n if (compMarginChartInstance) compMarginChartInstance.destroy();\n compMarginChartInstance = new Chart(ctx, {\n type: 'bar',\n data: {\n labels: [\n '腾讯音乐 (TME · 高效现金与订阅牛)',\n '网易云音乐 (Cloud Village · 社区文娱)',\n 'Spotify (SPOT · 全球流媒体龙头)'\n ],\n datasets: [\n {\n label: '净利润率 Net Profit Margin (%)',\n data: [27.5, 12.0, 8.5],\n backgroundColor: '#0284C7',\n borderRadius: 5,\n barThickness: 18\n },\n {\n label: '远期估值 P/E Ratio',\n data: [10.4, 14.0, 35.0],\n backgroundColor: '#10B981',\n borderRadius: 5,\n barThickness: 18\n }\n ]\n },\n options: {\n indexAxis: 'y',\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n },\n tooltip: {\n callbacks: {\n label: (ctx) => `${ctx.dataset.label}: ${ctx.parsed.x}${ctx.datasetIndex === 0 ? '%' : 'x'}`\n }\n }\n },\n scales: {\n x: {\n max: 40,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 } }\n },\n y: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n });\n }\n\n function initValEvolutionChart() {\n const ctx = document.getElementById('valEvolutionChart').getContext('2d');\n const colors = getChartColors();\n\n if (valEvolutionChartInstance) valEvolutionChartInstance.destroy();\n valEvolutionChartInstance = new Chart(ctx, {\n type: 'bar',\n data: {\n labels: ['2023', '2024', '2025', '2026E'],\n datasets: [\n {\n type: 'bar',\n label: '经调整 Non-IFRS 净利润 (亿元人民币)',\n data: [62.2, 81.5, 93.0, 98.5],\n backgroundColor: 'rgba(2, 132, 199, 0.85)',\n borderRadius: 5,\n barThickness: 32,\n yAxisID: 'y'\n },\n {\n type: 'line',\n label: '流通 ADS 股份总数 (百万股)',\n data: [3350, 3280, 3210, 3120],\n borderColor: '#10B981',\n backgroundColor: '#10B981',\n borderWidth: 3,\n pointRadius: 5,\n pointHoverRadius: 7,\n tension: 0.25,\n yAxisID: 'y1'\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n },\n tooltip: {\n callbacks: {\n label: (ctx) => ctx.dataset.yAxisID === 'y'\n ? `${ctx.dataset.label}: RMB ${ctx.parsed.y.toFixed(1)}亿`\n : `${ctx.dataset.label}: ${ctx.parsed.y}M 股`\n }\n }\n },\n scales: {\n x: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n },\n y: {\n type: 'linear',\n position: 'left',\n min: 40,\n max: 120,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => 'RMB ' + v + '亿' },\n title: { display: true, text: 'Non-IFRS 净利润 (亿元)', color: colors.text, font: { size: 11 } }\n },\n y1: {\n type: 'linear',\n position: 'right',\n min: 2800,\n max: 3600,\n grid: { drawOnChartArea: false },\n ticks: { color: '#10B981', font: { size: 11, weight: '600' }, callback: v => v + 'M' },\n title: { display: true, text: '流通 ADS 数量 (百万股)', color: '#10B981', font: { size: 11 } }\n }\n }\n }\n });\n }\n\n function updateChartsTheme() {\n initBizChart();\n initRadarChart();\n initCompMarginChart();\n initValEvolutionChart();\n }\n\n window.addEventListener('DOMContentLoaded', () => {\n loadKpiChecklist();\n updateDividendSimulator();\n initBizChart();\n initRadarChart();\n initCompMarginChart();\n initValEvolutionChart();\n });\n </script>\n</body>\n</html>"};
